
/* ═══════════════════════════════════════
   Transitions
   ═══════════════════════════════════════ */
.page-fade-enter-active {
  animation: fadeSlideIn 0.4s cubic-bezier(0.22, 1, 0.36, 1);
}
.page-fade-leave-active {
  animation: fadeSlideOut 0.25s cubic-bezier(0.4, 0, 1, 1);
}
@keyframes fadeSlideIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: none; }
}
@keyframes fadeSlideOut {
  from { opacity: 1; }
  to { opacity: 0; transform: translateY(-6px); }
}

.card-list-enter-active {
  animation: cardEnter 0.35s cubic-bezier(0.22, 1, 0.36, 1) both;
  animation-delay: calc(var(--i) * 0.05s);
}
.card-list-leave-active {
  animation: cardLeave 0.2s ease both;
}
.card-list-move {
  transition: transform 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}
@keyframes cardEnter {
  from { opacity: 0; transform: scale(0.92) translateY(8px); }
  to { opacity: 1; transform: none; }
}
@keyframes cardLeave {
  from { opacity: 1; }
  to { opacity: 0; transform: scale(0.95); }
}

/* ═══════════════════════════════════════
   Main Selector
   ═══════════════════════════════════════ */
.selector {
  padding: 24px 16px 20px;
  animation: selectorIn 0.5s ease both;
}
@keyframes selectorIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* ═══ Header ═══ */
.selector-header {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin-bottom: 20px;
}

.header-ornament {
  width: 50px;
  height: 12px;
  color: var(--sel-gold);
  .ornament-svg {
    width: 100%;
    height: 100%;
  }
}

.header-center {
  text-align: center;
}

.selector-title {
  font-family: var(--font-title);
  font-size: 20px;
  color: var(--sel-gold);
  letter-spacing: 10px;
  font-weight: normal;
  text-shadow: 0 0 24px rgba(201, 168, 76, 0.25);
}

.title-accent {
  width: 28px;
  height: 1.5px;
  margin: 5px auto;
  background: linear-gradient(90deg, transparent, var(--sel-accent), transparent);
  border-radius: 1px;
}

.selector-hint {
  font-size: 10.5px;
  color: var(--sel-text-muted);
  letter-spacing: 2.5px;
  margin-top: 3px;
}

/* ═══ Filter Bar ═══ */
.filter-bar {
  display: flex;
  gap: 6px;
  margin-bottom: 18px;
  padding: 0 4px 10px;
  overflow-x: auto;
  scrollbar-width: none; /* Firefox */
  -ms-overflow-style: none; /* IE/Edge */

  /* Create an elegant mask effect for horizontal scroll */
  mask-image: linear-gradient(90deg, black 90%, transparent 100%);
  -webkit-mask-image: linear-gradient(90deg, black 90%, transparent 100%);
}

.filter-bar::-webkit-scrollbar {
  display: none; /* Chrome/Safari */
}

.filter-btn {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 5px 12px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.02);
  color: var(--sel-text-muted);
  font-family: var(--font-text);
  font-size: 11px;
  cursor: pointer;
  transition: all 0.3s ease;
  letter-spacing: 1px;
  white-space: nowrap;

  .filter-icon {
    font-family: var(--font-title);
    font-size: 11px;
    opacity: 0.7;
  }

  &:hover {
    border-color: rgba(201, 168, 76, 0.2);
    color: var(--sel-text-sub);
    background: rgba(201, 168, 76, 0.04);
  }

  &.active {
    border-color: rgba(201, 168, 76, 0.3);
    color: var(--sel-gold);
    background: rgba(201, 168, 76, 0.08);
    box-shadow: 0 0 12px rgba(201, 168, 76, 0.08);

    .filter-icon {
      opacity: 1;
    }
  }
}

/* ═══ Script Grid ═══ */
.script-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

/* ═══ Script Card ═══ */
.script-card {
  --card-accent: var(--sel-accent);
  position: relative;
  border-radius: 8px;
  cursor: pointer;
  overflow: hidden;

  &.modern { --card-accent: #c41e3a; }
  &.ancient { --card-accent: #b8860b; }
  &.xianxia { --card-accent: #5b8dd9; }
  &.minguo { --card-accent: #a07850; }
  &.strategy {
    --card-accent: #8b0000;
    grid-column: 1 / -1; /* Make the strategy card span full width to emphasize "Large Script" */
  }

  &.strategy .card-body {
    background: linear-gradient(145deg, rgba(30, 20, 10, 0.85), rgba(40, 15, 15, 0.9));
    border: 1px solid rgba(255, 215, 0, 0.15);
  }

  &:hover {
    .card-shimmer { opacity: 1; }
    .card-body {
      border-color: rgba(var(--card-accent-rgb, 196, 30, 58), 0.3);
      transform: translateY(-1px);
      box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
    }
    .card-arrow {
      opacity: 1;
      transform: translateX(0);
    }
    .card-title {
      text-shadow: 0 0 12px rgba(201, 168, 76, 0.3);
    }
  }

  &:active .card-body {
    transform: scale(0.97);
  }
}

.card-shimmer {
  position: absolute;
  inset: 0;
  border-radius: 8px;
  background: radial-gradient(ellipse at 50% 0%, var(--card-accent), transparent 70%);
  opacity: 0;
  transition: opacity 0.4s;
  pointer-events: none;
  filter: blur(16px);
  z-index: 0;
}

.card-body {
  position: relative;
  z-index: 1;
  background: var(--sel-card-bg);
  border: 1px solid rgba(255, 255, 255, 0.04);
  border-radius: 8px;
  padding: 14px;
  transition: all 0.3s cubic-bezier(0.22, 1, 0.36, 1);
  backdrop-filter: blur(4px);
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}

.card-era {
  font-size: 9.5px;
  color: var(--card-accent);
  letter-spacing: 2px;
  font-weight: 500;
  opacity: 0.85;
}

.card-difficulty {
  display: flex;
  gap: 3px;
  align-items: center;
}

.diff-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.1);
  transition: background 0.2s;

  &.filled {
    background: var(--sel-gold);
    box-shadow: 0 0 3px rgba(201, 168, 76, 0.4);
  }
}

.card-title {
  font-family: var(--font-title);
  font-size: 15px;
  color: var(--sel-gold);
  font-weight: normal;
  letter-spacing: 1.5px;
  margin-bottom: 6px;
  transition: text-shadow 0.3s;
}

.card-subtitle {
  font-size: 10.5px;
  color: var(--sel-text-sub);
  line-height: 1.6;
  margin-bottom: 12px;
  opacity: 0.8;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 10px;
  border-top: 1px solid rgba(255, 255, 255, 0.04);
}

.card-heroine {
  font-size: 11.5px;
  color: var(--sel-text);
  font-family: var(--font-title);
  letter-spacing: 1px;
  display: flex;
  align-items: center;
  gap: 5px;
}

.heroine-mark {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--card-accent);
  box-shadow: 0 0 4px var(--card-accent);
}

.card-arrow {
  font-size: 16px;
  color: var(--sel-text-muted);
  opacity: 0;
  transform: translateX(-4px);
  transition: all 0.25s ease;
  font-weight: 300;
}

/* ═══════════════════════════════════════
   Detail View
   ═══════════════════════════════════════ */
.detail {
  padding: 16px;
  min-height: 100%;
}

.back-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 6px 12px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.03);
  color: var(--sel-text-sub);
  font-family: var(--font-text);
  font-size: 11px;
  cursor: pointer;
  transition: all 0.25s;
  margin-bottom: 20px;
  letter-spacing: 1px;

  .back-icon {
    font-size: 14px;
    line-height: 1;
    transition: transform 0.2s;
  }

  &:hover {
    border-color: rgba(201, 168, 76, 0.2);
    color: var(--sel-text);
    .back-icon { transform: translateX(-2px); }
  }
}

.detail-content {
  --card-accent: var(--sel-accent);
  &.modern { --card-accent: #c41e3a; }
  &.ancient { --card-accent: #b8860b; }
  &.xianxia { --card-accent: #5b8dd9; }
  &.minguo { --card-accent: #a07850; }
  &.strategy { --card-accent: #8b0000; }
}

.detail-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.detail-era {
  font-size: 10px;
  color: var(--card-accent);
  letter-spacing: 3px;
  font-weight: 500;
}

.detail-stars {
  .star {
    font-size: 11px;
    color: var(--sel-text-muted);
    margin-left: 1px;
    &.filled {
      color: var(--sel-gold);
      text-shadow: 0 0 4px rgba(201, 168, 76, 0.5);
    }
  }
}

.detail-title {
  font-family: var(--font-title);
  font-size: 22px;
  color: var(--sel-gold);
  letter-spacing: 3px;
  font-weight: normal;
  margin-bottom: 8px;
  text-shadow: 0 0 20px rgba(201, 168, 76, 0.25);
}

.detail-tagline {
  font-size: 12px;
  color: var(--sel-text-sub);
  line-height: 1.7;
  letter-spacing: 0.5px;
  padding-left: 10px;
  border-left: 2px solid var(--card-accent);
  opacity: 0.85;
}

.detail-divider {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 20px 0;
  justify-content: center;
}

.divider-dot {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--card-accent);
  opacity: 0.5;
}

.divider-line {
  width: 40px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--card-accent), transparent);
  opacity: 0.4;
}

.detail-desc {
  margin-bottom: 22px;

  p {
    font-size: 12px;
    color: var(--sel-text);
    line-height: 2;
    letter-spacing: 0.3px;
    opacity: 0.85;
  }
}

.detail-info {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-bottom: 22px;
  padding: 14px;
  background: rgba(255, 255, 255, 0.02);
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.04);
}

.info-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.info-label {
  font-size: 9.5px;
  color: var(--sel-text-muted);
  letter-spacing: 1.5px;
}

.info-value {
  font-size: 12px;
  color: var(--sel-text);
  font-family: var(--font-title);
  letter-spacing: 0.5px;

  &.heroine-name {
    color: var(--card-accent);
  }

  .star-sm {
    font-size: 9px;
    color: var(--sel-text-muted);
    &.filled {
      color: var(--sel-gold);
    }
  }
}

.detail-memories {
  margin-bottom: 28px;
}

.memories-label {
  font-size: 10px;
  color: var(--sel-text-muted);
  letter-spacing: 2px;
  margin-bottom: 10px;
  font-weight: normal;
}

.memory-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.memory-item {
  padding: 10px 12px;
  background: rgba(0, 0, 0, 0.2);
  border-radius: 6px;
  border-left: 2px solid var(--card-accent);
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.memory-key {
  font-size: 10px;
  color: var(--sel-text-muted);
  letter-spacing: 1px;
}

.memory-val {
  font-size: 11.5px;
  color: var(--sel-text);
  line-height: 1.6;
  opacity: 0.9;
}

/* ═══ Select Button ═══ */
.select-btn {
  position: relative;
  display: block;
  width: 100%;
  padding: 14px 0;
  border: 1px solid var(--card-accent);
  border-radius: 8px;
  background: rgba(var(--card-accent-rgb, 196, 30, 58), 0.08);
  color: var(--sel-text);
  font-family: var(--font-title);
  font-size: 14px;
  letter-spacing: 4px;
  cursor: pointer;
  overflow: hidden;
  transition: all 0.3s ease;

  &:hover {
    background: rgba(var(--card-accent-rgb, 196, 30, 58), 0.15);
    box-shadow: 0 0 24px rgba(var(--card-accent-rgb, 196, 30, 58), 0.2);
    transform: translateY(-1px);

    .btn-glow {
      opacity: 1;
    }
  }

  &:active {
    transform: scale(0.98);
  }
}

.btn-text {
  position: relative;
  z-index: 1;
}

.btn-glow {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 100%, var(--card-accent), transparent 70%);
  opacity: 0;
  transition: opacity 0.4s;
  filter: blur(12px);
}

/* ═══════════════════════════════════════
   Selected Scene
   ═══════════════════════════════════════ */
.selected-scene {
  position: relative;
  padding: 50px 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 200px;
  overflow: hidden;
}

.embers {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.ember {
  position: absolute;
  bottom: 0;
  border-radius: 50%;
  background: var(--sel-accent);
  opacity: 0;
  animation: rise linear infinite;
  box-shadow: 0 0 6px var(--sel-accent);
}

@keyframes rise {
  0% { opacity: 0; transform: translateY(0) scale(1); }
  15% { opacity: 0.9; }
  75% { opacity: 0.4; }
  100% { opacity: 0; transform: translateY(-140px) scale(0.2); }
}

.selected-content {
  text-align: center;
  animation: fadeSlideIn 0.6s ease;
  position: relative;
  z-index: 1;
}

.book-icon {
  font-size: 32px;
  margin-bottom: 14px;
  animation: bookFloat 2.5s ease-in-out infinite;
}
@keyframes bookFloat {
  0%, 100% { transform: translateY(0) rotate(0deg); }
  50% { transform: translateY(-5px) rotate(1deg); }
}

.selected-title {
  font-family: var(--font-title);
  font-size: 18px;
  color: var(--sel-gold);
  letter-spacing: 5px;
  margin-bottom: 10px;
  text-shadow: 0 0 20px rgba(201, 168, 76, 0.4);
}

.selected-sub {
  font-size: 11.5px;
  color: var(--sel-text-muted);
  letter-spacing: 2px;
  margin-bottom: 18px;
}

.loading-bar {
  width: 100px;
  height: 2px;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 1px;
  margin: 0 auto;
  overflow: hidden;
}

.loading-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--sel-accent), var(--sel-gold));
  border-radius: 1px;
  animation: loadProgress 2s ease-in-out infinite;
}
@keyframes loadProgress {
  0% { width: 0; transform: translateX(0); }
  50% { width: 70%; }
  100% { width: 100%; }
}
